const crypto = require('crypto');
const { execution, trigger, workflow = {} } = $input.first().json;

// Errors in a trigger node come in under `trigger` and have no execution.
const err = execution?.error ?? trigger?.error ?? {};
const where = execution?.lastNodeExecuted ?? (trigger ? 'trigger' : '?');
const detail = `${workflow.name} / ${where}: ${String(err.message || 'unknown error').slice(0, 300)}`;
console.error(`[lendloop] ${detail}`);

const secret = $env.N8N_TO_CONVEX_SECRET;
if (!secret) throw new Error('N8N_TO_CONVEX_SECRET is not set');
const body = JSON.stringify({
  kind: 'workflow_error',
  status: 'failed',
  idempotencyKey: `n8n-error:${workflow.id}:${execution?.id ?? Date.now()}`,
  detail,
});
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
return [{ json: { body, headers: { 'Content-Type': 'application/json', 'X-LendLoop-Timestamp': timestamp, 'X-LendLoop-Signature': signature } } }];
